2:00","title":"Back to hotel","duration":"0.5h","cost":"€12","notes":null,"mapsUrl":null,"bookingRef":null,"bags":null,"transit":null,"siteId":null,"optionGroup":null,"optionLabel":null,"primary":true,"kind":"transit","tickets":[],"mapPages":[],"guideIds":[]},{"id":"stop-day10-shower","time":"22:30","title":"Shower","duration":"","cost":null,"notes":null,"mapsUrl":null,"bookingRef":null,"bags":null,"transit":null,"siteId":null,"optionGroup":null,"optionLabel":null,"primary":true,"kind":"rest","tickets":[],"mapPages":[],"guideIds":[]},{"id":"stop-day10-sleep","time":"23:15","title":"Sleep","duration":"","cost":null,"notes":null,"mapsUrl":null,"bookingRef":null,"bags":null,"transit":null,"siteId":null,"optionGroup":null,"optionLabel":null,"primary":true,"kind":"rest","tickets":[],"mapPages":[],"guideIds":[]}]},{"id":"day-11","date":"2026-11-08","dateLabel":"Sunday, Nov 8","navLabel":"Sun Nov 8 · Transit home","city":"Transit to Home","type":"transit","headline":"The Journey Home","briefing":"Leonardo Express to FCO. Everyone flies FI 931 FCO→KEF in Economy, then FI 645 KEF→IAD — Hanna back in Business for the long leg; boys remain Economy. Home ~20:00.","weather":null,"sunrise":null,"sunset":null,"heroImage":null,"food":{"name":"Hotel / Terminal / Airplane","vibe":"Final espresso at the hotel; airport and cabin food thereafter.","mustTry":"Final espresso","hours":null,"cost":null},"highlights":[{"stopId":"stop-day11-fi931","title":"FI 931 FCO → KEF","time":"11:25","duration":"5h 05m","summary":"Everyone Economy on the short leg."},{"stopId":"stop-day11-fi645","title":"FI 645 KEF → IAD","time":"16:50","duration":"6h 40m","summary":"Hanna Business; boys Economy. Land 18:30."}],"stops":[{"id":"stop-day11-wake","time":"05:30","title":"Wake up","duration":"","cost":null,"notes":null,"mapsUrl":null,"bookingRef":null,"bags":null,"transit":null,"siteId":null,"optionGroup":null,"optionLabel":null,"primary":true,"kind":"rest","tickets":[],"mapPages":[],"guideIds":[]},{"id":"stop-day11-breakfast","time":"07:30","title":"Breakfast at the hotel","duration":"","cost":null,"notes":"Final espresso.","mapsUrl":null,"bookingRef":null,"bags":null,"transit":null,"siteId":null,"optionGroup":null,"optionLabel":null,"primary":true,"kind":"meal","tickets":[],"mapPages":[],"guideIds":[],"vibe":["Paid hotel breakfast"],"mustTry":["Final espresso"],"hours":"07:00 – 10:00"},{"id":"stop-day11-airport","time":"08:30","title":"Leonardo Express to FCO","duration":"1h","cost":"€56","notes":null,"mapsUrl":null,"bookingRef":null,"bags":null,"transit":null,"siteId":null,"optionGroup":null,"optionLabel":null,"primary":true,"kind":"transit","tickets":[],"mapPages":[],"guideIds":[]},{"id":"stop-day11-security","time":"09:25","title":"Airport & security","duration":"2h","cost":null,"notes":null,"mapsUrl":null,"bookingRef":null,"bags":null,"transit":null,"siteId":null,"optionGroup":null,"optionLabel":null,"primary":true,"kind":"transit","tickets":[],"mapPages":[],"guideIds":[]},{"id":"stop-day11-fi931","time":"11:25","title":"FI 931 FCO → KEF (all)","duration":"5h 05m","cost":"Plebs $1,313 pp; Royalty segment under A4RA46","notes":"Everyone Economy this leg. Land KEF 15:30. ~1h 20–25m layover.","mapsUrl":null,"bookingRef":"A38FNO (Plebs) / A4RA46 (Hanna)","bags":"Plebs: 1 carry-on + personal, 10kg max. Hanna: checked 32kg on long-haul booking.","transit":null,"siteId":"flight-hanna-iceland","optionGroup":null,"optionLabel":null,"primary":true,"kind":"transit","tickets":[{"id":"flight-hanna-iceland","label":"Hanna FCO→KEF","pages":["/images/tickets/flight-hanna-iceland/ticket-page-1.jpg","/images/tickets/flight-hanna-iceland/ticket-page-2.jpg","/images/tickets/flight-hanna-iceland/ticket-page-3.jpg"]}],"mapPages":[],"guideIds":["flight-hanna-iceland"]},{"id":"stop-day11-fi645","time":"16:50","title":"FI 645 KEF → IAD","duration":"6h 40m","cost":"Hanna $2,064.51 pp (A4X3SC)","notes":"Hanna Business; boys Economy. Land IAD 18:30.","mapsUrl":null,"bookingRef":"A4X3SC (Hanna Business)","bags":"Hanna: 1 checked 32kg + carry-on + personal; 10kg max personal & carry-on together","transit":null,"siteId":"flight-boy-dc","optionGroup":null,"optionLabel":null,"primary":true,"kind":"transit","tickets":[{"id":"flight-boy-dc","label":"Boy KEF→IAD","pages":["/images/tickets/flight-boy-dc/ticket-page-1.jpg","/images/tickets/flight-boy-dc/ticket-page-2.jpg","/images/tickets/flight-boy-dc/ticket-page-3.jpg"]},{"id":"flight-hanna-dc","label":"Hanna KEF→IAD","pages":["/images/tickets/flight-hanna-dc/ticket-page-1.jpg","/images/tickets/flight-hanna-dc/ticket-page-2.jpg","/images/tickets/flight-hanna-dc/ticket-page-3.jpg"]}],"mapPages":[],"guideIds":["flight-boy-dc","flight-hanna-dc"]},{"id":"stop-day11-land","time":"18:30","title":"Land at IAD","duration":"1h","cost":null,"notes":null,"mapsUrl":null,"bookingRef":null,"bags":null,"transit":null,"siteId":null,"optionGroup":null,"optionLabel":null,"primary":true,"kind":"transit","tickets":[],"mapPages":[],"guideIds":[]},{"id":"stop-day11-leave-airport","time":"19:30","title":"Leave the airport","duration":"0.5h","cost":null,"notes":null,"mapsUrl":null,"bookingRef":null,"bags":null,"transit":null,"siteId":null,"optionGroup":null,"optionLabel":null,"primary":true,"kind":"transit","tickets":[],"mapPages":[],"guideIds":[]},{"id":"stop-day11-home","time":"20:00","title":"Home","duration":"","cost":null,"notes":"Trip total ~$16,980.61.","mapsUrl":null,"bookingRef":null,"bags":null,"transit":null,"siteId":null,"optionGroup":null,"optionLabel":null,"primary":true,"kind":"rest","tickets":[],"mapPages":[],"guideIds":[]}]}]},"sites":[{"id":"tower-of-london","name":"Tower of London","aliases":["Tower","Crown Jewels"],"logistics":["Walk southeast from Apex City of London Hotel (~3–5 min) to the West Gate entrance.","Hours: 10:00–17:30; last admission 15:00.","Cost: £111 + £14 family audio (£37 adults / £18.50 under 15).","Try to catch the 14:30 or 15:00 Yeoman Warder tour.","Moat surrounds the fortress; the only way in is through Byward Tower."],"proTips":["Yeoman Warder tour: included with admission; every ~30 min near the entrance; 45–60 min; led by military veterans who live on site with their families.","Doesn''t run in rain (umbrella safety); does not include Crown Jewels or White Tower — see those on your own.","Pick up Family Audio Guide at the kiosk just past the entrance."],"history":["Historic castle and fortress founded in 1066; military history and royal armouries.","White Tower built by William the Conqueror in 1078 after 1066 to intimidate the Saxons; onion domes added in the 16th century for Queen Anne Boleyn''s coronation.","Crown Jewels: 23,000+ gemstones including Cullinan I; stolen once in 1671 by Colonel Thomas Blood, who was inexplicably pardoned.","Raven legend: the kingdom and fortress fall if the six resident ravens ever leave; the Ravenmaster feeds them raw meat and blood-soaked biscuits.","Torture here was tightly regulated — Privy Council permission required; only 48 recorded cases."],"route":["Byward Tower — defended the main entrance since the 13th century; original wooden portcullis (dropping gate) still in place.","Traitor''s Gate — Edward I water gate; Tudor prisoners including Anne Boleyn arrived here; note the extra-small second door.","Torture Tower / Lower Wakefield Tower — Tudor interrogation replicas; only 48 recorded torture cases.","Medieval Palace (St Thomas''s, Wakefield, Lanthorn) — Henry III / Edward I apartments; Wakefield vaulted ceiling and throne; Henry VI killed here; Oratory in St Thomas''s with recreated medieval altar where Edward I prayed.","White Tower — Royal Armouries (Henry VIII''s oversized decorated armour), Chapel of St John (11th-century); wooden stairs once removable/burnable for defense; also used as a prison.","Place of Executions — Anne Boleyn executed here.","Waterloo Barracks / Crown Jewels — Duke of Wellington; then Beauchamp Tower (famous prisoners)."],"attachments":[]},{"id":"london-wall","name":"London Wall","aliases":["Roman Wall","Londinium Wall"],"logistics":["Short walk after Tower of London viewpoint (~17:45 stop).","Free exterior fragment."],"proTips":["Look for the change in masonry where Roman courses meet medieval rebuild."],"history":["Built on a 200 AD Roman fort — first ~14 feet are Roman, then medieval.","Enclosed Londinium and dictated City of London boundaries for over a millennium.","At peak: ~2 miles long, 20 ft high, 8 ft thick; this fragment is one of the largest surviving sections."],"route":["View the surviving fragment near the Tower; note Roman lower courses vs medieval upper."],"attachments":[]},{"id":"harry-potter-studios","name":"Warner Bros. Studio Tour London — The Making of Harry Potter","aliases":["Harry Potter Studios","Leavesden","HP Studios"],"logistics":["Transit ~1.25h from Tower Hill via Euston Square → Watford Junction → studio shuttle.","Hours: 09:00–20:00. Cost: £188 tickets + £14.25 audio + lunch budget.","Sells out months ahead — book ASAP."],"proTips":["Grab free Activity Passports at entry (trivia, souvenir stamps, Golden Snitch scavenger hunt).","One-way system — cannot go backward after leaving the first soundstage into the Backlot.","Backlot is fully outdoors (Knight Bus, Privet Drive, Butterbeer) — bring a hooded jacket or umbrella in late October."],"history":["Housed at working Leavesden studios where all eight Harry Potter films were produced over ten years.","After Deathly Hallows Part 2 wrapped, the crew preserved thousands of props, costumes, and sets as a behind-the-scenes exhibition."],"route":["Hub / Tour Entrance / Experience Corridor — Ukrainian Ironbelly dragon suspended from the ceiling; short cinema intro then the screen lifts to reveal the entrance.","The Great Hall — solid York stone floor (built for a decade of filming), forced perspective, practical lighting in the ceiling.","Filmmakers & Interior Sets — Potions Classroom cauldrons stir via motion-triggered motors at Snape''s desk; Dumbledore''s office phone directories rebound in leather.","Ministry of Magic — largest set (30,000 sq ft); Forbidden Forest animatronics (Aragog, Hippogriff).","Backlot & Backlot Stage — Hogwarts Bridge; triple-decker Knight Bus weighted against tipping; Butterbeer Bar (vegan, non-alcoholic).","Gringotts & The Vaults — faux-marble pillars; ~38,000 pieces of rubber treasure in the Lestrange Vault; functional vault door.","1:24 Hogwarts model (86 artists, 2,500 fiber-optic lights); Wand Room (17,000+ boxes).","Quidditch & SFX/VFX — mechanical rigs and multi-axis motion bases.","Ministry of Magic — largest set (~30,000 sq ft), 9-meter fireplaces; green tiles are painted wood.","Creature Effects — prosthetics, internal servos, latex molds.","Wand Room — 17,000+ individually hand-painted wand boxes named for cast and crew.","Platform 9¾ — genuine 1937 Great Western Railway steam locomotive."],"attachments":[]},{"id":"magdalen-college","name":"Magdalen College","aliases":["Magdalen","Oxford Magdalen"],"logistics":["Hours: 10:00–16:00 Oct–Mar (winter). Cost: £10 per adult/person.","Must be at visitor gate right at 10:00 opening (Sunday Oxford branch).","On Fri Oxford option: taxi should drop you here first — closes earliest."],"proTips":["Focus on grounds, cloisters, chapel, and Deer Park / river atmosphere."],"history":["Working Oxford college balancing teaching with medieval architecture, cloisters, chapel, and Deer Park by the river.","C.S. Lewis debated literature here with J.R.R. Tolkien."],"route":["Beautiful grounds and medieval architecture.","Cloisters, chapel, river/Deer Park walk."],"attachments":[]},{"id":"radcliffe-square","name":"Radcliffe Square / Bodleian / Sheldonian / University Church","aliases":["Radcliffe Camera","Bodleian Library","Sheldonian Theatre","University Church of St Mary the Virgin"],"logistics":["University Church opens Sunday at 12:00. Exteriors free; Bodleian interior needs tour ticket."],"proTips":["Sunday mornings heavily restricted by collegiate services — exteriors + Christ Church Meadow if needed.","This cluster is the visual \"holy shit, I''m in Oxford\" impact."],"history":["Bodleian is among Europe''s oldest libraries (~400 years); the square is Oxford''s visual epicenter.","Surrounding architecture forms the historic epicenter of the university."],"route":["Walk the visual core: Bodleian Old Library quadrangle, Radcliffe Camera, Sheldonian Theatre, University Church."],"attachments":[]},{"id":"christ-church","name":"Christ Church","aliases":["Christ Church College","Christ Church Cathedral"],"logistics":["Hours: Mon–Sat 10:00–17:00. Sunday visitors often closed until 14:00.","Cost: ~£22.50 standard adult. Multimedia tour included with entry."],"proTips":["Prioritize for Max — more valuable than just walking Oxford streets."],"history":["Site dates to the 12th century; college and cathedral for the Diocese of Oxford.","Charles Dodgson (Lewis Carroll) was a mathematics don here.","Great Hall inspired the Harry Potter dining hall design."],"route":["Great Hall, Christ Church Cathedral, medieval cloisters."],"attachments":[]},{"id":"st-pauls-cathedral","name":"St. Paul''s Cathedral","aliases":["St Pauls","St. Paul''s"],"logistics":["Hours: 08:30–16:30 (last admission 16:00).","Exterior free; interior ~£48.50 — not worth it for a 45-min stop. Family ticket cheaper if going in.","Audio guide included with paid entry."],"proTips":["Not enough time for a full interior visit on this stop — exterior focus; optional 17:00 Choral Evensong if you want to see inside.","Can climb the dome if you go inside."],"history":["Rebuilt by Sir Christopher Wren after the Great Fire of London (1666).","Originally intended as pure white stone; gilding/gold accents associated with the Victorian era.","Apse took a direct WW2 hit — rebuilt as US memorial chapel (USA flag / Washington in glass)."],"route":["Focus on the massive dome and Whispering Gallery from the exterior vantage."],"attachments":[]},{"id":"trafalgar-square","name":"Trafalgar Square","aliases":["Trafalgar"],"logistics":["Free public square; illegal to feed pigeons."],"proTips":["Fountains allegedly installed to keep crowd sizes down."],"history":["Commemorates British naval victory at Trafalgar (1805), preventing Napoleon''s Channel invasion.","Nelson''s Column; some decorations cast from melted French cannons; fountains were partly meant to keep crowd sizes down."],"route":["Nelson''s Column and lion statues; note Whitehall / Banqueting House nearby."],"attachments":[]},{"id":"palace-of-westminster","name":"Palace of Westminster (Parliament)","aliases":["Parliament","Houses of Parliament","Westminster Palace"],"logistics":["Exterior viewing free. Seat of the UK government."],"proTips":["Can go inside on separate tickets if ever expanding the stop."],"history":["Medieval palace largely destroyed by fires in 1512 and 1834; today''s building is 19th-century Gothic Revival.","Westminster Hall once the biggest hall in Europe; wooden roof from 1397.","House of Commons met here to stay close to the king; nearby Banqueting House is where Charles I was executed in 1649.","Prime Minister lives at 10 Downing Street.","Center of power since ~1016; land used as a royal residence from the time of Cnut."],"route":["Exterior facade with Big Ben; Westminster Hall if inside access.","Westminster Hall — once among Europe''s largest halls; wooden roof from 1397; historic throne room associations."],"attachments":[]},{"id":"big-ben","name":"Queen Elizabeth Tower / Big Ben","aliases":["Big Ben","Elizabeth Tower"],"logistics":["Free exterior viewing."],"proTips":["Big Ben is the 13-ton bell inside, not the tower itself."],"history":["Clock accuracy controlled by adding/removing pre-decimal penny coins on the pendulum.","Hidden prison room about a third of the way up; last used in 1880 for a Member of Parliament.","“Big Ben” is the ~13-ton bell inside the Queen Elizabeth Tower."],"route":["Family photo with tower, Parliament, and Thames backdrop (best early morning)."],"attachments":[]},{"id":"westminster-bridge","name":"Westminster Bridge","aliases":[],"logistics":["Free. Cross for classic London views."],"proTips":["Original 1750 stone bridge was first across the Thames in 500 years."],"history":["Opened 1750 as a major engineering achievement."],"route":["Photo stop with Big Ben / Parliament / Thames."],"attachments":[]},{"id":"golden-jubilee-bridge","name":"Golden Jubilee Bridge","aliases":["Hungerford Bridge footbridges"],"logistics":["Free pedestrian crossing of the Thames."],"proTips":["Opened 2002 for QEII''s 50th accession anniversary; won 2003 RFAC Building of the Year."],"history":["Commemorative Thames crossing for the Golden Jubilee."],"route":["Cross for pictures toward Westminster."],"attachments":[]},{"id":"westminster-abbey","name":"Westminster Abbey","aliases":["Abbey"],"logistics":["Hours: 09:30–15:30. Cost: £64.26 (family structure: adult+child tickets + exhibit).","Use the provided audio guide."],"proTips":["Most important church in Britain — coronations, marriages, burials since 1066."],"history":["Royal coronation church since 1066; the most important church in Britain for crowning, marrying, and burying monarchs.","Unknown Soldier (WW1) — only unknown surrounded by royalty.","Tombs: Elizabeth I & Mary, Edward the Confessor (center), Newton, Churchill.","Lady Chapel — beautiful ceiling; WW2 fighter pilots window."],"route":["Unknown Soldier → Coronation Chair → Elizabeth & Mary tombs → Edward the Confessor → Poets''/famous tombs → Lady Chapel.","Tomb of the Unknown Warrior (WW1).","Coronation Chair — tradition dating to William the Conqueror.","Tomb of Edward the Confessor (founded the abbey; at the liturgical center).","Tombs/memorials of notable Britons including Isaac Newton and Winston Churchill.","Lady Chapel — ornate ceiling; window honoring WWII fighter pilots."],"attachments":[]},{"id":"horse-guards","name":"Horse Guards Parade / Officers Inspection","aliases":["Officers Inspection","Horse Guards","Changing of the Guard"],"logistics":["Officers Inspection (what we''re seeing): 11:00–11:10 Tue/Thu/Sat/Sun at Horse Guards Parade.","Changing of the Guard at Buckingham: 11:00–11:45 Mon/Wed/Fri/Sun (arrive by 10:30)."],"proTips":["Iconic red-coat guards — free street viewing.","Changing of the Guard at Buckingham Palace typically 11:00–11:45 (Mon/Wed/Fri/Sun).","Horse Guards Parade mounted change ~11:00–11:30 (Mon/Wed/Fri)."],"history":["British military pageantry at Horse Guards Parade."],"route":["Watch Officers Inspection from the parade ground edge; continue walk toward Buckingham."],"attachments":[]},{"id":"buckingham-palace","name":"Buckingham Palace","aliases":["Buck Palace","Buckingham"],"logistics":["Exterior walk free. State rooms open in summer only (ends ~late Sep)."],"proTips":["#1 attraction in London by footfall.","Best palace facade photo from Queen Victoria Memorial steps.","Blue Bridge in St James''s Park for framed palace-over-lake shot; Canada Gate on Green Park side."],"history":["The King''s official London residence; State Rooms open to visitors mainly in summer.","Eastern facade clad in Portland stone with center balcony."],"route":["Main gates (wrought iron, royal crests, gold) → facade/balcony → Queen Victoria Memorial → St James''s Park Blue Bridge.","Queen Victoria Memorial — marble/bronze with Winged Victory on top; good photo spot on the steps."],"attachments":[]},{"id":"shakespeare-globe","name":"Shakespeare''s Globe","aliases":["Globe","Globe Theatre"],"logistics":["Hours: 11:00–18:00. Cost: £87 guided (£30 adult / £13.50 under 16).","Official guided tours last ~60 minutes; tickets are emailed the day before."],"proTips":["Guided tour focuses on stage view and historical exhibition."],"history":["Replica of Shakespeare''s Elizabethan theatre. Original 1599 (Shakespeare held 12.5% share); burned 1613 after stage cannon misfire during Henry VIII.","Rebuilt with traditional Tudor methods (wooden pegs, no steel); holds ~1,500 spectators (about half the original capacity)."],"route":["Guided tour of yard, stage, and galleries; Golden Hind visit often bundled with guide ticket."],"attachments":[]},{"id":"golden-hind","name":"Golden Hind","aliases":["Golden Hinde","Golden Hidle"],"logistics":["Hours: 11:00–18:00. Cost included with Shakespeare''s Globe w/ guide on this itinerary."],"proTips":["Full-scale working replica — traditional shipbuilding, Italian hemp rigging, 22 handcrafted cannons."],"history":["Replica of Sir Francis Drake''s flagship — first English ship to circumnavigate the globe (1577–1580).","Replica has sailed 140,000+ miles and completed its own circumnavigation."],"route":["Deck walk and historic naval context beside the Globe."],"attachments":[]},{"id":"tower-bridge","name":"Tower Bridge","aliases":[],"logistics":["Hours: 09:30–18:00 (last admission 17:00). Cost: £42.50.","Ticket office on the west side of the North Tower; you can enter up to ~20 minutes after the time on the ticket.","After towers, follow Blue Line to historic Engine Rooms and gift shop under southern approach."],"proTips":["The good-looking bridge — London Bridge is the least impressive one west of it."],"history":["Completed 1894; towers 213 ft tall; bascules with 400-ton counterweights raise to 83° in ~5 min.","High walkways closed 1909 due to crime, reopened 1982. Steam engines replaced by electro-hydraulic in 1976."],"route":["Foundations (70,000 tons concrete) → suspension spans → bascules → high walkways (140 ft) → Engine Rooms via Blue Line."],"attachments":[]},{"id":"british-museum","name":"The British Museum","aliases":["British Museum","BM"],"logistics":["Hours: 10:00–17:00. Cost: £105 (timed entry — reserve ~2 months ahead).","Enter Main Gates on Great Russell Street. Bounce bag drop nearby (~£26.30)."],"proTips":["Follow Room numbers; don''t try to see everything — stick to the tactical route."],"history":["First public national museum in the world."],"route":["Ground Floor, Room 4 — Rosetta Stone: identical decree in Hieroglyphic, Demotic, and Ancient Greek; key to deciphering hieroglyphs; seized by the British in 1801.","Rooms 6–10 — Lamassu / colossal winged bulls (5 legs); Assyrian Lion Hunt (Ashurbanipal).","Room 18 — Parthenon Sculptures / Elgin Marbles (Phidias, 447–432 BC); ongoing repatriation dispute with Greece.","Level 3, Rooms 54–59 — Standard of Ur (Room 56, ~2600 BC): wooden box with War/Peace mosaic panels.","Rooms 40–51 — Sutton Hoo ship burial (Room 41): early-7th-century Anglo-Saxon royal burial; rare iron and tinned-copper helmet.","Room 67 — Sarangbang Korean scholar''s study (no nails); Joseon Dynasty moon jars.","Room 56 — Royal Game of Ur: ~4,500-year-old playable game; rules reconstructed from a cuneiform tablet in the 1980s.","Room 40 — Lewis Chessmen: 12th-century walrus ivory; berserkers biting their shields."],"attachments":[]},{"id":"piccadilly","name":"Piccadilly / Regent Street / Carnaby","aliases":["Piccadilly Circus","Regent Street","Carnaby Street","Fortnum & Mason"],"logistics":["Free street wandering; evening lights at Piccadilly Circus."],"proTips":["Fortnum & Mason — official royal grocer since 1707."],"history":["Piccadilly Circus is London''s neon crossroads — often called the Times Square of London."],"route":["Walk west on Piccadilly (Fortnum & Mason) → north on Regent Street flagships → northeast into Carnaby Street boutiques."],"attachments":[]},{"id":"arc-du-carrousel","name":"Arc de Triomphe du Carrousel","aliases":["Arc Du Carrousel","Carrousel Arch"],"logistics":["Free. Adjacent to Louvre Courtyard / Tuileries axis."],"proTips":["Enter Louvre via underground stairs by this arch to bypass outdoor pyramid lines.","Stand under central arch and look west — frames Concorde obelisk → Champs-Élysées → Arc de Triomphe."],"history":["Built by Napoleon to celebrate the victory at Austerlitz; monumental gateway toward the Tuileries.","Quadriga on top is a copy — Napoleon looted Venice''s Horses of St Mark but had to return them.","Eight rose-marble Corinthian columns."],"route":["View Quadriga; sightline west through the historic axis; descend underground to Carrousel du Louvre entrance.","Stand under the central arch and look west — framed axis through Place de la Concorde''s obelisk, the Champs-Élysées, and the Arc de Triomphe."],"attachments":[]},{"id":"palais-royal","name":"Jardin du Palais Royal","aliases":["Palais Royal","Jardin De Palais Royal"],"logistics":["Hours: 08:00–22:30. Cost: Free."],"proTips":["Famous black-and-white column installation (1980s Buren columns)."],"history":["Old royal residence courtyard gardens."],"route":["Walk the colonnades and striped columns before breakfast / Louvre."],"attachments":[]},{"id":"louvre","name":"The Louvre","aliases":["Musée du Louvre","Louvre Museum"],"logistics":["Hours: 09:00–18:00; closed Tuesdays. Courtyard opens 07:00.","Cost: €64 family line (adults €32; kids free). Largest art museum (~35,000 pieces).","Enter via underground Carrousel stairs by Arc du Carrousel; pick up audio guide on Level -1.","Largest art museum in the world (~35,000 works on display)."],"proTips":["Follow La Joconde signs for Mona Lisa; don''t fight the crowd — view then move on."],"history":["Built in the 1200s as a fortress, became royal residence, museum since 1793 (Revolution)."],"route":["Level 1 Denon — Mona Lisa (Room 711); Coronation of Napoleon; Liberty Leading the People (713).","Room 703 — Winged Victory of Samothrace (2nd century BC) at the top of the Daru staircase, staged like a ship''s prow.","Level -1 — Medieval Louvre moat/walls (Room 135, Philippe Auguste 1190).","Room 348 — Salle des Caryatides (oldest surviving hall; four carved women hold the balcony); Sleeping Hermaphroditus (mattress carved later by Bernini).","Richelieu — Palace of Darius / Near Eastern antiquities; Frieze of Archers (Room 233); Winged Bulls of Khorsabad (Room 229, ~30-ton, five legs); Code of Hammurabi (7-ft black basalt stele, “eye for an eye”).","Level 1, Denon Wing, Room 711 — Mona Lisa (Leonardo); commoner wife; stolen in 1911 by an employee who hid in a broom closet.","Room 705 — French Crown Jewels (Napoleon & Louis XV crowns); display inspired the Hall of Mirrors.","Level 1 — Napoleon III apartments (lavish drawing rooms).","Level 0, Room 345 — Venus de Milo (arms already missing when found in 1820).","Room 345 — Borghese Gladiator."],"attachments":[]},{"id":"sainte-chapelle","name":"Sainte-Chapelle","aliases":["Sainte Chapelle","Holy Chapel"],"logistics":["Hours: 09:00–19:00. Cost: ~€22 adult / kids free (+ €6 audio); itinerary budgets €60 family.","Airport-style security — allow 15–30 min.","About €22 per adult, kids free, ~€6 audio guide (confirm current pricing)."],"proTips":["Upper chapel glass is the payoff — look up."],"history":["Built 1242–1248 by Louis IX to house the Crown of Thorns (relic cost more than the chapel).","Paris began on this island — Romans as Lutetia; Clovis later made it a royal/religious center."],"route":["Lower chapel (commoners — blue ceiling/French crest, red Spanish columns).","Upper chapel — 1,113 stained-glass scenes; great shrine/altar (once 22 relics).","Original medieval glass still in place."],"attachments":[]},{"id":"seine-cruise","name":"Vedettes du Pont Neuf Seine River Cruise","aliases":["Seine Cruise","Vedettes du Pont Neuf"],"logistics":["Hours: 10:30–22:00. Cost: €60. Maps: https://maps.app.goo.gl/QPihrEWs6RPuNb4o8"],"proTips":["Use as foot recovery between Sainte-Chapelle and Notre-Dame."],"history":["Historic bridges and monuments from water level."],"route":["Board at Pont Neuf; loop past Louvre, Musée d''Orsay, Notre-Dame façades."],"attachments":[]},{"id":"notre-dame","name":"Notre-Dame Cathedral","aliases":["Notre Dame","Nôtre-Dame"],"logistics":["Hours: 08:00–19:00. Free entry; booking opens 2 days before.","Two lines (with/without tickets). Highly pickpocketed area.","Bell towers €16 extra (book online; 424 stairs; 5 min at summit). Treasury €12 at desk."],"proTips":["Reserve timed entry 2 days out; keep bags zipped."],"history":["Took ~200 years to build; burned 2019; reopened Dec 2024.","Gargoyles to scare evil spirits; headless angel is St Denis."],"route":["Three Rose Windows; Grand Organ (8,000 pipes); 29 chapels; Transept; Treasury (Crown of Thorns); optional Bell Towers."],"attachments":[]},{"id":"arc-de-triomphe","name":"Arc de Triomphe","aliases":["Arc De Triomphe","Arch de Triomphe","Étoile"],"logistics":["Hours: 10:00–22:30. Base free; top ~€64 (itinerary: not worth it).","Be there exactly at 18:30 for daily rekindling of the flame (since 1923)."],"proTips":["Rekindling uninterrupted even during WWII occupation."],"history":["Commissioned by Napoleon 1806 after Austerlitz; completed 1836; remains passed under in 1840.","Tomb of the Unknown Soldier installed 1921. 50 m tall; 660 generals engraved (dead underlined)."],"route":["Outer reliefs — Triumph of 1810 / La Marseillaise / Resistance / Peace; top soldier motifs; Unknown Soldier flame at 18:30."],"attachments":[]},{"id":"trocadero","name":"Trocadéro","aliases":["Trocadero","Place du Trocadéro"],"logistics":["Free viewpoint. Best before/at sunrise for empty Eiffel shots."],"proTips":["Wear formal attire for the family Paris picture."],"history":["Classic axis view across the Seine to the Eiffel Tower."],"route":["Stand on the Trocadéro terrace centerline for the symmetrical tower shot."],"attachments":[]},{"id":"versailles","name":"Palace of Versailles","aliases":["Versailles","Château de Versailles","Palace of Versailles"],"logistics":["Hours: 09:00–17:30; closed Mondays. Cost: €112 (itinerary).","Enter Entrance A timed entry. Head to North Ministers Wing by 09:45 for guided tour (bypasses security).","Bring kids'' passports for age checks; umbrella; driver license for golf cart. Buy 2-way RER C tickets."],"proTips":["Fountains mainly summer. Food on-site overpriced — bring from Carette if needed.","Lunch option La Flottille; Metairie food truck; or packed."],"history":["Started as Louis XIII''s hunting lodge; expanded by Louis XIV (72-year reign; Versailles spending was a huge share of state wealth).","Hall of Mirrors: German Empire proclamation 1871; Treaty of Versailles 1919."],"route":["~10:00 Guided tour of the King''s Private Apartment — narrow passages, Clock Room, Corner Room, Louis XVI library, Games Room.","~11:45 State Apartments — seven rooms named for Roman deities; Diana/billiards; Apollo/throne room.","Empire Rooms (Napoleon crossing Alps) → Pavillon d''Orléans → Light of Liberty VR.","Gardens: Latona → Apollo Fountain → Grand Canal → lunch → Grand Trianon → Marie Antoinette''s Hamlet.","~11:30 Hall of Mirrors — 73 m, 357 mirrors (a flex against Venice''s mirror monopoly); German Empire proclaimed here 1871; Treaty of Versailles 1919."],"attachments":[]},{"id":"eiffel-tower","name":"Eiffel Tower","aliases":["Tour Eiffel","Eiffel"],"logistics":["Hours: 09:00–00:00. Cost: €110.20 (itinerary 2nd-floor goal).","Target entry ~17:00 with 30 min line buffer for sunset from 2nd floor."],"proTips":["2nd floor is best; summit optional in November.","Take 674 stairs down from 2nd floor. Lights ~10 min after sunset; sparkles on the hour until ~23:00."],"history":["Built for 1889 World''s Fair in 2 years; 7,000 metric tons of puddle iron.","Names of 72 French scientists engraved around the first floor; the iron structure can expand/bend up to ~18 cm in summer heat.","Can bend/grow up to 18 cm in summer heat.","Secret bunker under the South pillar.","Con artist Victor Lustig “sold” it for scrap twice in the 1920s."],"route":["Ascend to 2nd floor for sunset; watch hourly sparkle; optional stair descent."],"attachments":[]},{"id":"catacombs","name":"Catacombs of Paris","aliases":["Catacombes","Paris Catacombs"],"logistics":["Hours: 09:45–20:30; closed Monday. Cost: €91. Book ~7 days ahead to the hour.","Metro 6 Bir-Hakeim → Denfert-Rochereau. ~55°F year-round.","About 55°F year-round underground."],"proTips":["Not for the claustrophobic; many stairs; no large bags."],"history":["Created in the late 18th century to relieve overflowing Paris cemeteries; ossuary lined with the bones of millions.","Emptying took 12 years via nightly wagons; Héricart de Thury organized decorative walls in 1810."],"route":["Walk ossuary corridors — skulls/femurs arranged; plaques name source churches."],"attachments":[]},{"id":"pantheon","name":"Pantheon","aliases":["Pantheon Rome","Pantheon di Roma"],"logistics":["Hours: 09:00–18:00. Free on National Unity Day (normally €20).","Two lines (cash vs credit) — pick the shorter. Best ~1h before open/close."],"proTips":["Judgement call: if line is crazy, continue to Piazza Navona and retry later (or Friday).","Offset the rest of the afternoon by 1.75h if you skip/wait."],"history":["Rebuilt by Hadrian 125–128 AD (kept Agrippa''s inscription). Best-preserved Roman temple; now a church.","Perfect sphere ~140 ft tall/wide; concrete dome thins with height.","Tombs: first king of Italy, Queen Margherita (pizza namesake), Raphael.","16 monolithic Egyptian granite columns; bronze roof beams reused for St Peter''s altar."],"route":["Enter rotunda → oculus light → tombs → columns → dome thickness story."],"attachments":[]},{"id":"piazza-navona","name":"Piazza Navona","aliases":["Piazza Novona","Navona"],"logistics":["Free. Optional Stadium of Domitian underground ~€9–13."],"proTips":["Oval shape preserves the ancient stadium footprint."],"history":["Built on Stadium of Domitian (80 AD); 17th-c. Baroque showcase under Pope Innocent X."],"route":["Three fountains: Fontana dei Quattro Fiumi (center, Egyptian obelisk), del Moro (south), del Nettuno (north)."],"attachments":[]},{"id":"ponte-umberto","name":"Ponte Umberto I","aliases":["Ponte Umberto","Umberto Bridge"],"logistics":["Free bridge. Maps: https://maps.app.goo.gl/LuJRMLz3fuBaR2Pi7"],"proTips":["Must be at sunset or night for the St. Peter''s view — daytime is weaker."],"history":["Bridge aligned for classic dome-of-St-Peter''s sightline."],"route":["Stand mid-span facing west/southwest for St. Peter''s Basilica framed over the Tiber."],"attachments":[]},{"id":"spanish-steps","name":"Spanish Steps","aliases":["Scalinata di Trinità dei Monti"],"logistics":["Free. DO NOT sit — €400 fine. Expect crowds."],"proTips":["Best view from the top at Trinità dei Monti."],"history":["Built 1723–1725 to bridge to Trinità dei Monti; 135 steps.","18th/19th c. foreigners'' quarter; packed with hopeful models historically."],"route":["Ascend or view from top; do not sit on steps."],"attachments":[]},{"id":"trevi-fountain","name":"Trevi Fountain","aliases":["Fontana di Trevi","Trevi"],"logistics":["€2 fee to enter lower basin area 09:00–22:00 (check current rules).","Check live cam for crowds when possible."],"proTips":["Toss coin over left shoulder with right hand (back toward fountain) to guarantee return to Rome."],"history":["Baroque fountain completed 1762; terminal of Acqua Vergine aqueduct.","Neptune / sea sculptures dominate the facade."],"route":["Approach from side streets if possible; coin toss; photos of Neptune group."],"attachments":[]},{"id":"largo-gaetana-agnesi","name":"Largo Gaetana Agnesi","aliases":["Large Catena Agnesi","Largo Catena Agnesi"],"logistics":["Free elevated viewpoint above Colosseo Metro. Arrive ~30 min before opening for empty shots."],"proTips":["Wear formal attire for the family Rome picture with Colosseum backdrop."],"history":["Modern overlook positioned for classic Colosseum photography."],"route":["Frame Colosseum without crowd foreground; continue downhill to Arch of Constantine."],"attachments":[]},{"id":"arch-of-constantine","name":"Arch of Constantine","aliases":["Constantine Arch"],"logistics":["Hours aligned with Colosseum/Forum complex 08:30–16:30 (last admission 15:30).","Included in Colosseum ticket. Meeting point for many tours."],"proTips":["Enter Palatine/Forum from here — leaving through a gate means you can''t re-enter."],"history":["Largest surviving Roman triumphal arch; built 312 AD for Constantine''s victory over Maxentius.","Chi-Rho vision (''in this sign, conquer''). Much decoration reused from Marcus Aurelius / Hadrian monuments.","Constantine''s vision of the Chi-Rho (“in this sign, conquer”); also marks his decennalia (10 years of rule)."],"route":["Exterior reliefs → enter archaeological park toward Forum / Palatine."],"attachments":[]},{"id":"roman-forum","name":"Roman Forum","aliases":["Forum","Foro Romano"],"logistics":["Included in Colosseum ticket. Hours: 08:30–16:30 (last admission 15:30)."],"proTips":["Follow Via Sacra; don''t exit the gates if you still need Palatine/Colosseum access."],"history":["Political, religious, and economic heart of ancient Rome; valley between the Palatine and Capitoline hills."],"route":["Via Sacra → Temple of Venus and Rome → Arch of Titus → Basilica of Constantine → Temple of Romulus → Antoninus & Faustina → House of Vestals → Temple of Divus Julius → Curia Julia → Septimius Severus Arch → Temple of Saturn.","Via Sacra — main triumphal route.","Temple of Venus and Rome (Hadrian; among the largest temples).","Arch of Titus — reliefs of soldiers carrying the Menorah from the 70 AD Jerusalem siege.","Temple of Antoninus and Faustina — best preserved; later a church; column grooves from medieval scavengers.","Curia Julia / Senate House — well preserved; doors are replicas (originals at San Giovanni).","Temple of Saturn — eight iconic columns; once the state treasury."],"attachments":[]},{"id":"palatine-hill","name":"Palatine Hill","aliases":["Palatine"],"logistics":["Included in Colosseum ticket. Hours: 08:30–16:30 (last admission 15:30)."],"proTips":["Best elevated views of Colosseum, Forum, and Circus Maximus."],"history":["Centermost of the Seven Hills; Romulus and Remus legend — Romulus kills Remus over a wall dispute and founds Rome on 21 Apr 753 BC.","Imperial palaces — Domus Flavia / Flavian Palace (92 AD)."],"route":["Flavian Palace (marble-clamp holes in walls) → Stadium of Domitian (sunken garden) → Circus Maximus viewing platforms."],"attachments":[]},{"id":"colosseum","name":"Colosseum","aliases":["Colosseo","Flavian Amphitheatre"],"logistics":["Hours: 08:30–16:30 (last admission 15:30). Cost: €52 (itinerary).","Tickets painful — book 30 days ahead at 04:00 for best; 7 days for OK. Arrive 30 min early.","Need separate tickets for Top/Underground. App audio works only inside."],"proTips":["Pivot if tickets fail: start Caracalla; hire guide (~$600); queue 06:00; Forum/Palatine only; Via dei Fori Imperiali views."],"history":["Flavian Amphitheatre commissioned ~70–72 AD by Vespasian; opened 80 AD by Titus; Domitian added the upper level and underground.","Named after Nero''s 30 m Colossus statue. Taller than Statue of Liberty without pedestal.","Later cemetery, fortress, quarry (iron-clamp holes). Consecrated 1749."],"route":["Four seating levels (1st for senators; 4th wooden seating for commoners) and four main entrances (east for gladiators, west for the dead).","Underground — 28 lifts (8 operators each) → second floor museum / inner ring photos.","Underground (hypogeum) — ~28 lifts around the outer rim, each worked by ~8 people; cages released animals onto the arena."],"attachments":[]},{"id":"baths-of-caracalla","name":"Baths of Caracalla","aliases":["Caracalla","Terme di Caracalla"],"logistics":["Hours: 09:00–16:30 (last admission 15:30). Cost: €44. No prebook needed.","Get the VR headset. Uber ~€10 from Monti (~1 mile)."],"proTips":["VR helps reconstruct the scale — use it."],"history":["Built 212–216 AD by Caracalla; functioned until 537 AD when Ostrogoths cut aqueducts.","~62 acres; could host ~1,600 bathers at once; hypocaust floor heating with wood-fired furnaces in tunnels (slaves/oxen).","Also had public libraries, gymnasiums, and saunas; intricate mosaic floors."],"route":["Hypocaust floor heating (slave/oxen wood furnaces) → mosaic floors → caldarium/tepidarium/frigidarium volumes."],"attachments":[]},{"id":"circus-maximus","name":"Circus Maximus","aliases":["Circo Massimo"],"logistics":["Free open park. Skip and Uber if exhausted."],"proTips":["Stand under Palatine for the commoner''s view of the emperor''s palace."],"history":["Premier chariot-racing stadium; 150,000–250,000 spectators."],"route":["Walk the immense footprint; view up under the Palatine for the commoners'' angle on the emperor''s palace."],"attachments":[]},{"id":"capitoline-hill","name":"Capitoline Hill / Piazza del Campidoglio","aliases":["Campidoglio","Capitol Hill","Capital Hill"],"logistics":["Free piazza. Maps: https://maps.app.goo.gl/68VnYPt5RAQAgzg37"],"proTips":["Michelangelo turned the square 180° to face papal authority."],"history":["Citadel of early Rome; smallest but most important hill politically/religiously.","By 1530s a muddy ''goat hill''; Pope Paul III commissioned Michelangelo''s redesign.","Marcus Aurelius statue is a 1981 laser replica; the original survived because Christians thought it was Constantine; legend says Judgment Day comes when the last gold flakes fall off.","Michelangelo rotated the square 180° toward papal authority and designed the 12-pointed star pavement (finished 1940)."],"route":["Enter Michelangelo''s star-pattern pavement → Marcus Aurelius → descend toward Trajan via San Pietro in Carcere."],"attachments":[]},{"id":"trajans-column","name":"Trajan''s Column","aliases":["Trajan Column","Colonna Traiana"],"logistics":["Free exterior viewing."],"proTips":["Spiral band widens upward as an optical illusion; originally painted with miniature bronze weapons."],"history":["Erected 113 AD for Trajan''s Dacian wars; ~125 ft tall; stacked ~17×30-ton marble drums; Trajan''s golden urn once at the base.","Golden urn with ashes at base. Trajan statue replaced by St Peter in 1587.","Story in order: base (crossing the Danube), middle (permanent bridge), top (Dacian capital falls; King Decebalus takes his own life)."],"route":["Read the spiral chronologically: Danube crossing → bridge building → Dacian capital / Decebalus suicide."],"attachments":[]},{"id":"altar-of-the-fatherland","name":"Altar of the Fatherland","aliases":["Altare della Patria","Vittoriano","Wedding Cake","Typewriter"],"logistics":["Hours: 09:30–19:30; rooftop elevator last admission 18:45. Cost: €36 elevator (base free).","No prebook — buy on site; usually no line."],"proTips":["Elevator to the roof is worth it for the all-Rome panorama."],"history":["Honors Victor Emmanuel II, first king of unified Italy. Locals: ''Typewriter'' / ''Wedding Cake''.","Tomb of the Unknown Soldier added 1921 with eternal flame."],"route":["Unknown Soldier flame at base → glass elevators to terrace panorama."],"attachments":[]},{"id":"st-peters-basilica","name":"St. Peter''s Basilica","aliases":["Saint Peter''s Basilica","San Pietro","St Peters"],"logistics":["Hours: 07:00–19:10; dome stairs open 08:00. Cost: €40 dome (buy on site — do not pre-buy).","551 steps (343 with elevator — worth it). Knees and shoulders covered; bring passport.","Dome stairs open at 08:00; buy the dome ticket on site."],"proTips":["Arrive early before security lines swell."],"history":["Site of Caligula''s chariot stadium where Nero blamed and executed Christians; St. Peter was crucified upside down nearby.","New basilica 1506–1626. Michelangelo''s Pietà (only signed work; behind glass after 1972 attack).","Largest church in the world; new basilica built 1506–1626 over Vatican Hill."],"route":["St Peter''s Square obelisk (Caligula 37 AD) → mosaics (not paintings) → High Altar (''Peter is here'') → bronze canopy (Pantheon bronze) → dome → Pietà → optional rooftop 3D exhibit.","Dome — design/painting associated with Michelangelo.","Pietà — carved from a single block when Michelangelo was 24; his only signed work; attacked with a hammer in 1972; now behind bulletproof glass.","Rooftop behind the dome — newer 3D exhibit area guarded by Swiss Guards."],"attachments":[]},{"id":"vatican-museums","name":"Vatican Museums & Sistine Chapel","aliases":["Vatican Museum","Sistine Chapel","Musei Vaticani"],"logistics":["Hours: 08:00–20:00; closed Sunday and holidays. Cost: €140 (itinerary).","Book ahead. Max tour size 25. End at Sistine; then optionally restart at own pace.","End the guided tour at the Sistine Chapel; max tour size ~25.","After the tour, go back toward the beginning (don''t exit) and continue at your own pace."],"proTips":["No photos in Sistine (enforced). Keep moving through pinches near Raphael Rooms / Chapel."],"history":["~70,000 works, ~9 miles of corridors; collection pushed forward when Pope Julius II acquired the Laocoön in the early 16th century."],"route":["Pinacoteca — The Transfiguration (Raphael''s final unfinished painting; he died at 37); St. Jerome (Leonardo; fingerprints visible; once cut up and used as tabletop/stool cover).","Pinecone Courtyard — Sphere Within Sphere; Egyptian / Chiaramonti / Pio Clementino (Apollo Belvedere, Laocoön, Belvedere Torso).","Raphael Rooms — Battle of the Milvian Bridge; School of Athens (Plato has Leonardo''s face; Michelangelo broods on the steps); Disputation of the Sacrament; The Parnassus.","Sistine Chapel — ceiling (Creation of Adam: tension in the negative space; God''s red mantle echoes a brain cross-section; Eve tucked under God''s arm); Last Judgment painted ~25 years later after the Sack of Rome (darker tone; St. Bartholomew holds flayed skin with Michelangelo''s face).","Exit via Bramante Staircase / Carriage Pavilion as routed.","Pio Clementino — Apollo Belvedere; Laocoön and His Sons (unearthed 1506; Michelangelo watched it come out of the ground); Belvedere Torso (Michelangelo refused to “restore” it and called himself a pupil of the Torso).","Gallery of Tapestries; Gallery of Maps (~120 m corridor, surprisingly accurate)."],"attachments":[]},{"id":"castel-sant-angelo","name":"Castel Sant''Angelo","aliases":["Castel Sant Angelo","Hadrian''s Mausoleum","Castel Sanit'' Angelo"],"logistics":["Hours: 09:00–19:30. Cost: €38. Book ~3 months ahead when possible."],"proTips":["Great views from the top terrace."],"history":["Commissioned 134 AD by Hadrian as mausoleum; Visigoths looted ashes 410.","In 590 AD Pope Gregory saw Archangel Michael sheathing his sword (omen the plague was ending) — hence the name.","1527: Pope Clement VII escaped siege via Passetto di Borgo (800 m corridor to Vatican).","In 1538 Benvenuto Cellini was imprisoned here and broke a leg escaping on bedsheets."],"route":["Bridge/square (historic execution site) → spiral Roman funeral ramp → Sale Papali frescoed rooms → upper terrace views.","Bridge/square — centuries of public executions by the papal executioner Mastro Titta."],"attachments":[]},{"id":"piazza-del-popolo","name":"Piazza del Popolo","aliases":["People''s Square"],"logistics":["Free. Tour bus pickup for Pompeii ~07:00 (bus departs 07:30)."],"proTips":["Be there by 07:00 — don''t cut it close."],"history":["Grand northern gate entrance into Rome; primary site for public executions until 1826 (guillotine/mallet).","Central Egyptian obelisk — oldest/tallest in Rome, from Ramses II (13th c. BC); brought by Augustus in 10 BC after defeating Cleopatra; originally stood in the Circus Maximus.","Name means “People''s Square.”"],"route":["Obelisk center → twin churches → meet tour at designated pickup."],"attachments":[]},{"id":"pompeii","name":"Pompeii","aliases":["Pompei"],"logistics":["Hours: 09:00–17:00 (1 Nov–30 Mar; else to 19:00). Included in €556 tour package.","Bring water (working fountains). Very little shade. Only small bags allowed."],"proTips":["Stay with guide for efficiency on a 2.5h window; note stepping stones and grid."],"history":["Destroyed 24 Aug 79 AD under ~20 feet of ash after a ~3-day eruption; city covered ~4 square miles (Manhattan is ~7) with ~20,000 residents.","Ancient Roman commercial hub frozen in time."],"route":["General — stepping stones to cross streets; Roman grid (cardo N–S, decumanus E–W) meeting at the Forum.","Theaters & gladiator barracks → Amphitheatre (oldest stone, 80 BC) → Forum Granary casts.","Forum Baths → House of the Faun (Alexander Mosaic replica) → Lupanar → Villa of the Mysteries if time.","House of the Vettii — noted for the “vomitorium” / banquet context and well-preserved decoration.","Forum — political and economic heart; Temple of Jupiter rededicated to the Capitoline Triad with underground treasury vaults.","Basilica — city hall, largest building; three civic halls; Building of Eumachia; Macellum food market.","Theatres — Large (~5,000) and Small (~1,500, originally roofed); gladiator barracks (wall sockets for an upper master''s floor).","Forum / Stabian Baths — hypocaust heating with hollow walls and floors.","Lupanar — brothel; explicit frescoes served as a visual “menu.”","Villa of the Mysteries — quieter; Pompeian Red frescoes of a secret Dionysian cult."],"attachments":[]},{"id":"mt-vesuvius","name":"Mt. Vesuvius","aliases":["Vesuvius","Mount Vesuvius","Mt Vesuvius"],"logistics":["30–40 min hike to crater rim. Noticeably cooler/windier at summit.","Path is loose volcanic gravel — wear good grip shoes. Included in Pompeii tour."],"proTips":["Bring a layer and water even if warm in Pompeii."],"history":["Active stratovolcano that buried Pompeii and Herculaneum in 79 AD."],"route":["Hike rim path → peer into active crater → panoramic Bay of Naples views."],"attachments":[]},{"id":"phantom-of-the-opera","name":"Phantom of the Opera","aliases":["Phantom"],"logistics":[],"proTips":[],"history":[],"route":[],"attachments":[]},{"id":"bounce-bag-storage","name":"Bounce Bag Storage","aliases":["Bounce"],"logistics":[],"proTips":[],"history":[],"route":[],"attachments":[]},{"id":"eurostar-london-paris","name":"Eurostar London → Paris","aliases":["Eurostar"],"logistics":[],"proTips":[],"history":[],"route":[],"attachments":[]},{"id":"pizza-gelato-class","name":"Pizza & Gelato Cooking Class","aliases":["Piazza Mattei","pizza class"],"logistics":[],"proTips":[],"history":[],"route":[],"attachments":[]},{"id":"flight-boys-london","name":"Boys flight to London","aliases":["FI 644"],"logistics":[],"proTips":[],"history":[],"route":[],"attachments":[]},{"id":"flight-hanna-london","name":"Hanna flight to London","aliases":["FI 642"],"logistics":[],"proTips":[],"history":[],"route":[],"attachments":[]},{"id":"flight-boy-dc","name":"Boy flight to DC","aliases":[],"logistics":[],"proTips":[],"history":[],"route":[],"attachments":[]},{"id":"flight-hanna-dc","name":"Hanna flight to DC","aliases":["FI 645"],"logistics":[],"proTips":[],"history":[],"route":[],"attachments":[]},{"id":"flight-hanna-iceland","name":"Hanna flight to Iceland","aliases":["FI 931"],"logistics":[],"proTips":[],"history":[],"route":[],"attachments":[]},{"id":"sainte-chapelle-visitor-guide","name":"Sainte-Chapelle Visitor Guide","aliases":["Sainte Chapelle guide"],"logistics":[],"proTips":[],"history":[],"route":[],"attachments":[{"id":"sainte-chapelle-visitor-guide-att","label":"Visitor guide","pages":["/images/guides/sainte-chapelle-visitor-guide/attach-page-1.jpg","/images/guides/sainte-chapelle-visitor-guide/attach-page-2.jpg"]}]}],"assets":{"sites":{"british-museum":{"photo":"/images/sites/british-museum.jpg"},"louvre":{"photo":"/images/sites/louvre.jpg"},"versailles":{"photo":"/images/sites/versailles.jpg"},"trevi-fountain":{"photo":"/images/sites/trevi.jpg"},"colosseum":{"photo":"/images/sites/colosseum.jpg"},"st-peters-basilica":{"photo":"/images/sites/vatican.jpg"},"vatican-museums":{"photo":"/images/sites/vatican.jpg"},"shakespeare-globe":{"photo":"/images/sites/globe.jpg"},"pompeii":{"photo":"/images/sites/pompeii.jpg"},"baths-of-caracalla":{"photo":"/images/sites/baths-map.jpg"},"tower-of-london":{"photo":"/images/sites/tower-of-london.jpg"},"harry-potter-studios":{"photo":"/images/sites/harry-potter.jpg"}},"tickets":{},"maps":{}}}'::jsonb,
